VIDEO = {'footer': 'CORS Done Right  ·  Security Basics  ·  Java', 'poster': {'headline': [('CORS', 'text'), ('DONE RIGHT', 'accent')], 'taglines': [('CORS decides who may read an answer, not who may send a request', 'gold')], 'before': {'code': 'Access-Control-Allow-Origin: https://evil.example', 'note': 'A reflected origin', 'tag': 'BEFORE'}, 'after': {'code': 'Access-Control-Allow-Origin: https://partner.example', 'note': 'An exact allow-list', 'tag': 'AFTER'}}, 'highlight': {'console_green': ['THE LIST', 'WHAT EACH PAGE GETS', 'THE ANSWER TO GET'], 'console_rose': ["THE BANK'S LOG", 'THE POLICY'], 'console_amber': ['THE REQUEST', 'THE PREFLIGHT', "THE BROWSER'S CHECK", 'WHAT THE PAGE GETS', 'THE ANSWERS', 'HOW THE SUFFIX', 'THE ANSWER ('], 'console_cyan': ['THE ORIGINS', 'THE SIMPLE-REQUEST RULE']}}
